	""
}

local function _0x_decode(_0x_data, _0x_k)
	local _0x_len = #_0x_data
	local _0x_out = {}
	local _0x_idx = 1
	local _bxor = _b32.bxor
	local _lshift = _b32.lshift
	local _rshift = _b32.rshift
	local _bor = _b32.bor
	local _band = _b32.band
	local _schar = string.char
	local _sbyte = string.byte

	local _0x_i = 1
	while _0x_i <= _0x_len do
		local _c1 = _0x_map[_sbyte(_0x_data, _0x_i)] or 0
		local _c2 = _0x_map[_sbyte(_0x_data, _0x_i + 1)] or 0
		local _b3 = _sbyte(_0x_data, _0x_i + 2)
		local _b4 = _sbyte(_0x_data, _0x_i + 3)
		local _c3 = _0x_map[_b3] or 0
		local _c4 = _0x_map[_b4] or 0

		local _n = _bor(_lshift(_c1, 18), _lshift(_c2, 12), _lshift(_c3, 6), _c4)

		_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 16), 255), _0x_k))
		_0x_idx = _0x_idx + 1

		if _b3 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_rshift(_n, 8), 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		if _b4 ~= 61 then
			_0x_out[_0x_idx] = _schar(_bxor(_band(_n, 255), _0x_k))
			_0x_idx = _0x_idx + 1
		end
		_0x_i = _0x_i + 4
	end
	return table.concat(_0x_out)
end

local function launchCoreScript()
    local segments = {}
    for idx, c in ipairs(_0x_chunks) do
        segments[idx] = _0x_decode(c, _0x_key)
    end
    local source = table.concat(segments)
    local fn, err = (loadstring or load)(source)
    if not fn then
        warn("[Ziro Hub] Falha ao compilar payload: " .. tostring(err))
        return
    end
    return fn()
end

-- ============================================================================
-- PERSISTENT KEY ENGINE & SERVER HOP SYNCHRONIZATION
-- ============================================================================
local function retrieveLastKey()
    local key = nil

    -- 1. Tentativa via memoria global persistente (getgenv / shared)
    pcall(function()
        if getgenv and getgenv()._ZIRO_ACTIVE_KEY and type(getgenv()._ZIRO_ACTIVE_KEY) == "string" then
            key = getgenv()._ZIRO_ACTIVE_KEY
        elseif shared and shared._ZIRO_ACTIVE_KEY and type(shared._ZIRO_ACTIVE_KEY) == "string" then
            key = shared._ZIRO_ACTIVE_KEY
        end
    end)
    if key and key ~= "" then return key:gsub("%s+", ""):upper() end

    -- 2. Tentativa direta via readfile (sem dependencia de isfile)
    pcall(function()
        if readfile then
            local content = readfile(SAVE_FILE_NAME)
            if content and type(content) == "string" and content ~= "" then
                key = content
            end
        end
    end)
    if key and key ~= "" then return key:gsub("%s+", ""):upper() end

    -- 3. Fallback com isfile se existir no executor
    pcall(function()
        if isfile and isfile(SAVE_FILE_NAME) and readfile then
            local content = readfile(SAVE_FILE_NAME)
            if content and type(content) == "string" and content ~= "" then
                key = content
            end
        end
    end)

    if key and key ~= "" then
        return key:gsub("%s+", ""):upper()
    end
    return nil
end

local function persistKey(validKey)
    local cleanKey = validKey:gsub("%s+", ""):upper()

    -- Salva na sessao em memoria
    pcall(function()
        if getgenv then getgenv()._ZIRO_ACTIVE_KEY = cleanKey end
        if shared then shared._ZIRO_ACTIVE_KEY = cleanKey end
    end)

    -- Salva no disco do executor
    pcall(function()
        if writefile then
            writefile(SAVE_FILE_NAME, cleanKey)
        end
    end)

    -- Propagacao automatica para o proximo servidor via queue_on_teleport
    pcall(function()
        local qot = queue_on_teleport or (syn and syn.queue_on_teleport) or (fluxus and fluxus.queue_on_teleport)
        if qot then
            qot('pcall(function() if getgenv then getgenv()._ZIRO_ACTIVE_KEY = "' .. cleanKey .. '" end end)')
        end
    end)
end

local function invalidateKey()
    pcall(function()
        if writefile then writefile(SAVE_FILE_NAME, "") end
        if delfile then delfile(SAVE_FILE_NAME) end
        if getgenv then getgenv()._ZIRO_ACTIVE_KEY = nil end
        if shared then shared._ZIRO_ACTIVE_KEY = nil end
    end)
end

-- ============================================================================
-- VERIFICACAO ATIVA OBRIGATORIA A CADA INICIALIZACAO / SERVER HOP
-- (Testa primeiramente a ultima chave usada para manter o fluxo continuo)
-- ============================================================================
local candidateKey = retrieveLastKey()
local initialErrorMsg = nil

if candidateKey and candidateKey ~= "" then
    -- Executa obrigatoriamente a validacao criptografica toda vez
    local ok, msg = validateKey(candidateKey)
    if ok then
        -- Chave 100% valida: preserva e avanca no fluxo automatico sem parada
        persistKey(candidateKey)
        notifyUser("Ziro Hub | Autenticacao", "Chave ativa autorizada! Carregando sistemas...", 3)
        task.spawn(launchCoreScript)
        return
    else
        -- Chave expirada, corrompida ou revogada: impede a entrada do usuario
        invalidateKey()
        initialErrorMsg = "Ultima chave expirada ou invalida. Digite uma nova chave."
        notifyUser("Ziro Hub | Acesso Bloqueado", initialErrorMsg, 4)
    end
end

